<template>
  <div class="containerSiteInfo">
    <h1>位点信息 - 样本: {{ sampleName }}</h1>

    <div class="search-bar">
      <input
          type="text"
          class="form-control"
          v-model="searchQuery"
          placeholder="搜索碱基位置信息..."
      />
    </div>
    <table class="table">
      <thead>
      <tr>
        <th>碱基位置</th>
        <th>参考碱基</th>
        <th>突变碱基</th>
        <th>总深度</th>
        <th>异质性</th>
        <th>类型</th>
      </tr>
      </thead>
      <tbody>
      <tr v-for="site in filteredSites" :key="site.id">
        <td>{{ site.base_position }}</td>
        <td>{{ site.reference_base }}</td>
        <td>{{ site.mutant_base }}</td>
        <td>{{ site.total_depth }}</td>
        <td>{{ site.heterogeneity }}%</td>
        <td>{{ site.type }}</td>
      </tr>
      </tbody>
    </table>
    <nav  class="pagination">
      <button v-if="totalPages > 1" class="btn btn-outline-primary" @click="prevPage" :disabled="currentPage === 1">
        上一页
      </button>
      <span v-if="totalPages > 1">第 {{ currentPage }} 页，共 {{ totalPages }} 页</span>
      <button v-if="totalPages > 1" class="btn btn-outline-primary" @click="nextPage" :disabled="currentPage === totalPages">
        下一页
      </button>
      <button class="btn-back" @click="goBack">
        返回
      </button>
    </nav>
  </div>
</template>

<script setup>
import { ref, computed, onMounted } from 'vue'
import { useRoute } from 'vue-router'
import router from "@/router"
import axios from "axios"

// 获取路由参数
const route = useRoute()
const sampleName = route.query.sampleName

// 响应式数据
const sites = ref([])
const searchQuery = ref('')
const currentPage = ref(1)
const itemsPerPage = 10

// 生命周期
onMounted(() => {
  fetchData()
})

// 方法定义
const fetchData = async () => {
  try {
    const response = await axios.get(`/table/getMitochondrialDetailDetails?name=${sampleName}`)
    sites.value = response.data.data
  } catch (err) {
    console.error('获取数据失败:', err)
  }
}

const goBack = () => {
  router.go(-1)
}

const prevPage = () => {
  if (currentPage.value > 1) currentPage.value--
}

const nextPage = () => {
  if (currentPage.value < totalPages.value) currentPage.value++
}

// 计算属性
const filteredSites = computed(() => {
  return sites.value
      .filter(site => site.original_data_name === sampleName)
      .filter(site => {
        const query = searchQuery.value.toLowerCase()
        return site.base_position.toString().toLowerCase().includes(query)
      })
      .slice((currentPage.value - 1) * itemsPerPage, currentPage.value * itemsPerPage)
})

const totalPages = computed(() => {
  return Math.ceil(
      sites.value.filter(site => site.original_data_name === sampleName).length / itemsPerPage
  )
})
</script>


<style>
body {
  font-family: Arial, sans-serif;
  margin: 0;
  padding: 20px;
  background-color: #f5f5f5;
}

.containerSiteInfo {
  padding: 20px;
  border-radius: 8px;
  height: 770px;
  width: 100%; /* 使用百分比宽度 */
  box-sizing: border-box; /* 确保内边距包含在宽度内 */
}

h1 {
  color: #333;
  margin-bottom: 20px;
}

.table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 20px;
}

.table th,
.table td {
  padding: 12px 15px;
  text-align: left;
  border-bottom: 1px solid #ddd;
  white-space: nowrap; /* 防止表格内容换行 */
  overflow: hidden;
  text-overflow: ellipsis; /* 超出部分显示省略号 */
}

.table th {
  background-color: #f8f9fa;
  font-weight: bold;
}

.btn-back {
  margin-right: 20px;
  padding: 8px 12px;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

.table tr:hover {
  background-color: #f1f1f1;
}

.btn {
  padding: 6px 12px;
  border-radius: 4px;
  cursor: pointer;
  display: inline-block;
  text-decoration: none;
}

.btn-primary {
  background-color: #007bff;
  color: white;
  border: none;
}

.btn-primary:hover {
  background-color: #0056b3;
}

.search-bar {
  margin-bottom: 20px;
}

.form-control {
  width: 100%;
  padding: 8px 12px;
  border: 1px solid #ddd;
  border-radius: 4px;
}

.pagination {
  display: flex;
  justify-content: center;
  margin-top: 20px;
}

.pagination button {
  margin: 0 5px;
  padding: 5px 10px;
}
</style>